// TH16 v1.00a Extra final boss, Boss5 (5th non-spell), st07bs.ecl.txt:477-559.
// Independent invulnerable shell per validation.md; real boss enemy carries the attack.

const TIME_LIMIT: int = 4324;      // 120 opening buffer + 4200 source interrupt window + 4
const OPENING_BUFFER: int = 120;

const TH16_SHARD: int = 512;       // source etSprite(0, 10, 13): type 10, color 13

// Enemy shared slots (source $I0 plus this card's movement bookkeeping).
const SI_FIRE_COUNT: int = 0;      // source $I0 (50 while $A > 0, then 100)
const SI_TICK: int = 1;            // movement tick since t0 (line 526)
const SI_RAMP_START: int = 2;      // active moveRandRel start tick, -1 = inactive
const SI_NARROW: int = 3;          // 1 after Boss5_at2 sets moveLimit(0,128,240,64)

const SF_REL_X: int = 0;           // accumulated REL-layer offset (moveRandRel)
const SF_REL_Y: int = 1;
const SF_DIR_C: int = 2;           // moveRandRel direction unit vector
const SF_DIR_S: int = 3;

// Source 534/547 moveRandRel(60, 4, 1.9f): pick one fixed direction from the
// current FINAL position and player x (movement.md moveRand recipe), then move
// with speed 1.9*(1-k/60) for k=1..60 on the REL layer.
sub move_rand() {
    var a: int = 0;
    var r: int = rand(65536) - 32768;
    if $self_x < -25fx {
        a = r / 3;
    } else if $self_x > 25fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(SF_DIR_C, cos(a as angle));
    set_self_fx(SF_DIR_S, sin(a as angle));
    set_self_int(SI_RAMP_START, self_int(SI_TICK) - 1);
    // The tick for this frame was already armed by card_wait; re-arm it with k=1.
    arm_tick(self_int(SI_TICK));
}

// Source 400/401: movePos(0,356) is the spawn position; movePosTime(600,0,0,128)
// is a linear ABS glide (the later 440/280/120 re-issues continue the same line).
// Source 504/505 limits are applied here every tick; source 405/404 resets are
// handled by move_reset().
sub arm_tick(t: int) {
    var ay: fx = 128fx;
    if t < 600 { ay = 356fx - 0.38fx * t; }
    var rx: fx = self_fx(SF_REL_X);
    var ry: fx = self_fx(SF_REL_Y);
    var rs: int = self_int(SI_RAMP_START);
    if rs >= 0 {
        var k: int = t - rs;
        if k >= 1 && k <= 60 {
            var sp: fx = 1.9fx * ((60 - k) as fx) / 60fx;
            rx = rx + sp * self_fx(SF_DIR_C);
            ry = ry + sp * self_fx(SF_DIR_S);
            set_self_fx(SF_REL_X, rx);
            set_self_fx(SF_REL_Y, ry);
        }
    }
    var px: fx = rx;
    var py: fx = ay + ry;
    if self_int(SI_NARROW) != 0 {
        if py < 96fx { py = 96fx; }
        if py > 160fx { py = 160fx; }
    } else {
        if py < 0fx { py = 0fx; }
        if py > 448fx { py = 448fx; }
    }
    if px < -120fx { px = -120fx; }
    if px > 120fx { px = 120fx; }
    // ECL phase 2 arms the next movement tick; phase 5 integrates it, so the
    // next frame's ECL reads the source position for that tick.
    move_vel_xy(0, px - $self_x, py - $self_y, EASE_LINEAR);
}

sub move_tick() {
    var t: int = self_int(SI_TICK) + 1;
    set_self_int(SI_TICK, t);
    arm_tick(t);
}

// Source 536/549 moveReset() inside the firing loop: clear the movement velocity
// and interpolation state but keep the absolute path (the next tick is re-issued
// by the movePosTime below it in source).
sub move_reset() {
    set_self_int(SI_RAMP_START, -1);
}

sub card_wait(n: int) {
    for i in 0..n {
        wait(1);
        move_tick();
    }
}

// Source Boss5_at(561-584): fixed-direction (aim mode 3) 1-way x 3-layer wave,
// sprite 10/13, speed 3/2.5/2, etDist 32, offset (0,-24), EX ANIM a=1.
// The birth ANIM itself is omitted per policy; its -4*velocity birth shift is kept.
sub fire_wave(a: angle) {
    var ux: fx = cos(a);
    var uy: fx = sin(a);
    for q in 0..3 {
        var sp: fx = 3fx - 0.5fx * (q as fx);
        var net: fx = 32fx - 4fx * sp;
        var bx: fx = $self_x + net * ux;
        var by: fx = $self_y - 24fx + net * uy;
        _ = fire(TH16_SHARD, 13, bx, by, sp, a, none, none);
    }
}

// Source Boss5_at async call: %C = %ANGLE_PLAYER once, then %C += step every
// 3-frame wave, %I0 waves.
async sub boss5_at(step: angle) {
    var c: angle = aim_player();
    var n: int = self_int(SI_FIRE_COUNT);
    for i in 0..n {
        fire_wave(c);
        c = c + step;
        wait(3);
    }
}

// Source Boss5_at2(586-592): wait(600); moveReset(); moveLimit(0,128,240,64).
async sub boss5_at2() {
    wait(600);
    set_self_int(SI_RAMP_START, -1);
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    set_self_int(SI_NARROW, 1);
}

// Source Boss5() 480-559. Omitted per policy: previous-card bullet clears
// (483/486/495/498 and TIMEOUT branches), killAllAsync/enmKillAll handoff,
// spellEnd/funcSet(0)/laserCancel, capture/drop/score resets, dropSeason,
// ANM/anmPlay/playSound, setInterrupt/lifeMarker/stars (phase timer and the
// invulnerable shell take over).
async sub boss5_main() {
    // Source Boss() common entry 38-39: setHurtbox(40,40) -> r20, setHitbox(48,48) -> r24.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // movePos(0, 356) is the spawn position (pattern below).
    wait(120);                              // source wait(120)
    // moveLimit(0,224,240,448): x[-120,120], y[0,448], enforced by arm_tick.
    wait(60);                               // source wait(60)
    // $A = 600; movePosTime(600,0,0,128); @Boss5_at2() async; $I0 = 50
    set_self_int(SI_TICK, 0);
    set_self_int(SI_RAMP_START, -1);
    set_self_int(SI_NARROW, 0);
    set_self_int(SI_FIRE_COUNT, 50);
    set_self_fx(SF_REL_X, 0fx);
    set_self_fx(SF_REL_Y, 0fx);
    move_tick();                            // arm source movement tick 1 at t0
    spawn boss5_at2();
    spawn boss5_at(8deg);
    spawn boss5_at(-8deg);
    var frames_a: int = 600;                // source $A
    loop {
        // Boss5_1328
        card_wait(100);
        move_rand();
        card_wait(60);
        move_reset();
        frames_a = frames_a - 160;
        if frames_a <= 0 { set_self_int(SI_FIRE_COUNT, 100); }
        spawn boss5_at(8deg);               // goto Boss5_1760
        spawn boss5_at(-8deg);
        // Boss5_1760
        card_wait(100);
        move_rand();
        card_wait(60);
        move_reset();
        frames_a = frames_a - 160;
        if frames_a <= 0 { set_self_int(SI_FIRE_COUNT, 100); }
        spawn boss5_at(8deg);               // goto Boss5_2192 -> Boss5_1328
        spawn boss5_at(-8deg);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 356fx, 13000, 0, 0, 0, boss5_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
